  let lock = @fs.open(
    directory + "/worker.lock",
    mode=ReadWrite,
    create_mode=OpenOrCreate,
    permission=0o600,
  )
  defer lock.close()
  if !lock.try_lock(Exclusive) {
    return
  }
  let state = @json.parse(@fs.read_file(directory + "/state.json").text())
  validate_state(state)
  let forwarding = match field(state, "localPort") {
    Some(Json::Number(value, ..)) =>
      ["-L", "127.0.0.1:\{value.to_int()}:127.0.0.1:47121"]
    None if field(state, "connection") == Some(Json::string("ssh")) => []
    _ => raise AdapterError("Missing tunnel port")
  }
  let enabled = directory + "/enabled"
  let mut adopted = try {
    check_tunnel(state, directory)
    true
  } catch {
    _ => false
  }
  set_field(state, "tunnelDirectory", Json::string(directory))
  let idle_timer = if idle_timeout(state) is Some(_) {
    Some(IdleTimer::{ elapsed: 0, seen: false, epoch: -1, previous: None, })
  } else {
    None
  }
  let mut attempt = 0
  let mut monitoring = false
  let mut monitor_attempt = 0
  defer @async.protect_from_cancel(async fn() {
    stop_tunnel_master(state, directory)
  })
  while @fs.exists(enabled) {
    if pause_request(directory) is Some(request) {
      if idle_timer is Some(timer) {
        timer.previous = None
      }
      stop_tunnel_master(state, directory)
      tunnel_status(directory, "paused")
      while @fs.exists(enabled) && pause_request(directory) == Some(request) {
        @fs.write_file(directory + "/pause-ack", request, permission=0o600)
        @async.sleep(100)
      }
      continue
    }
    if @fs.exists(directory + "/probe-request") {
      @fs.remove(directory + "/probe-request")
    }
    tunnel_status(directory, "connecting")
    git_relay_status(directory, "pending")
    let mut terminal = false
    @async.with_task_group(async fn(group) {
      let idle_busy : Ref[Bool] = { val: false, }
      let idle_done : Ref[Bool] = { val: false, }
      let mut idle_started = false
      group.spawn_bg(no_wait=true, async fn() {
        while @fs.exists(enabled) && !@fs.exists(directory + "/paused") {
          @async.sleep(100)
        }
        raise AdapterError("Tunnel disabled or paused")
      })
      monitoring = true
      let current = worker_workspace(state, directory)
      save_diagnostic(
        "monitor-identity",
        match current {
          None => "missing"
          Some(value) if field(value, "uid") == field(state, "workspaceUid") =>
            "matched"
          _ => "replaced"
        },
        tunnel_directory=directory,
        expected_workspace_uid=required(state, "workspaceUid"),
        observed_workspace_uid?=current.map(value => required(value, "uid")),
      )
      guard current is Some(current) &&
        field(current, "uid") == field(state, "workspaceUid") else {
        if @fs.exists(enabled) {
          @fs.remove(enabled)
        }
        terminal = true
        tunnel_status(directory, "ownership-error")
        return
      }
      let status = required(current, "workspaceStatus")
      save_diagnostic("monitor-workspace", status, tunnel_directory=directory)
      if status == "NotFound" {
        terminal = true
        @fs.remove(enabled)
        tunnel_status(directory, "ownership-error")
        return
      }
      if status != "Running" {
        if status == "Stopped" {
          idle_reset(state, "workspace_stopped")
        }
        monitoring = true
        tunnel_status(
          directory,
          if status == "Stopped" {
            "workspace-stopped"
          } else {
            "workspace-busy"
          },
        )
        return
      }
      monitoring = false
      @fs.mkdir(
        required(state, "socketDirectory"),
        permission=0o700,
        allow_exist=true,
      )
      let sink = @process.redirect_to_file("/dev/null", shared=true)
      defer sink.close()
      let (errors, stderr) = @process.read_from_process()
      defer errors.close()
      let classified = group.spawn(
        async fn() { tunnel_errors(errors) },
        no_wait=true,
      )
      let child = if adopted {
        save_diagnostic("orca-tunnel", "adopted", tunnel_directory=directory)
        None
      } else {
        Some(
          @process.spawn(
            group,
            "ssh",
            ssh_args(
              state,
              lease=required(state, "socketDirectory") + "/primary-proxy.lock",
            ) +
            [
              "-M",
              "-S",
              control_socket(state, directory),
              "-N",
              "-o",
              "ExitOnForwardFailure=yes",
              "-o",
              "ServerAliveInterval=10",
              "-o",
              "ServerAliveCountMax=3",
            ] +
            forwarding,
            stdin=@process.redirect_from_file("/dev/null"),
            stdout=sink,
            stderr~,
            no_wait=true,
          ),
        )
      }
      adopted = false
      let git_enabled = @async.with_timeout(10000, async fn() {
        git_forwarding_enabled(state)
      })
      let mut next_probe = @env.now()
      let mut next_check = @env.now()
      let mut failures = 0
      let mut connected = false
      while @fs.exists(enabled) {
        if idle_done.val {
          monitoring = true
          break
        }
        if idle_busy.val {
          @async.sleep(100)
          continue
        }
        if child is Some(child) && child.try_wait() is Some(code) {
          save_diagnostic(
            "orca-tunnel",
            "disconnected",
            exit_code=code,
            error_type=@async.with_timeout(1000, async fn() {
              classified.wait()
            }) catch {
              _ => "process_exit"
            },
            tunnel_directory=directory,
          )
          break
        }
        if (!connected || child is None) && @env.now() >= next_check {
          let alive = try {
            check_tunnel(state, directory)
            true
          } catch {
            _ => false
          }
          if !alive {
            if connected || child is None {
              break
            }
            @async.sleep(100)
            continue
          }
          next_check = @env.now() + 1000
        }
        if @env.now() >= next_probe ||
          (connected && @fs.exists(directory + "/probe-request")) {
          match relay_readiness(state, directory, git_enabled) {
            Ready => {
              failures = 0
              attempt = 0
              if !connected {
                if @fs.exists(directory + "/server-enabled") {
                  @async.with_timeout(connection_timeout_ms(), async fn() {
                    ignore(recover_server(state))
                  })
                }
                connected = true
                monitoring = false
                monitor_attempt = 0
                git_relay_status(
                  directory,
                  if git_enabled {
                    "ready"
                  } else {
                    "disabled"
                  },
                )
                tunnel_status(directory, "connected")
              }
              if @fs.exists(directory + "/probe-request") {
                @fs.remove(directory + "/probe-request")
              }
              next_probe = @env.now() + 10000
              if !idle_started &&
                idle_timer is Some(timer) &&
                @fs.exists(directory + "/idle-enabled") {
                idle_started = true
                group.spawn_bg(no_wait=true, async fn() {
                  idle_supervisor(state, timer, idle_busy, idle_done) catch {
                    error =>
                      save_diagnostic(
                        "idle-monitor",
                        "failed",
                        error_type="monitor_failed",
                        error_message=redact_credentials(error.to_string()),
                        tunnel_directory=directory,
                      )
                  }
                })
              }
            }
            Unsupported => {
              terminal = true
              tunnel_status(directory, "unsupported")
              break
            }
            WaitingForGitHelper => {
              failures = 0
              connected = false
              git_relay_status(directory, "unavailable")
              tunnel_status(directory, "checking")
              next_probe = @env.now() + 1000
            }
            Retry(reason) => {
              failures += 1
              connected = false
              git_relay_status(directory, "unavailable")
              tunnel_status(directory, "checking")
              save_diagnostic(
                "relay-recovery",
                "failed",
                attempt=failures,
                error_type=reason,
                tunnel_directory=directory,
              )
              if failures >= 2 {
                break
              }
              next_probe = @env.now()
              continue
            }
          }
        }
        @async.sleep(100)
      }
    }) catch {
      error => {
        let message = match error {
          AdapterError(message) => Some(redact_credentials(message))
          _ => None
        }
        if @fs.exists(enabled) && !@fs.exists(directory + "/paused") {
          save_diagnostic(
            "orca-tunnel",
            "process-error",
            tunnel_directory=directory,
            error_type=if monitoring {
              "workspace_query_failed"
            } else {
              "connection_failed"
            },
            error_message?=message,
          )
        }
      }
    }
    stop_tunnel_master(state, directory, verify=true)
    if terminal {
      return
    }
    if @fs.exists(directory + "/paused") {
      continue
    }
    if monitoring && @fs.exists(enabled) {
      let delay = configured_timing_ms(
        "ORCA_ENV_DEVSY_TEST_MONITOR_DELAY_MS",
        monitor_delay(monitor_attempt),
      )
      save_diagnostic(
        "monitor-wait",
        "waiting",
        attempt=monitor_attempt,
        retry_delay_ms=delay,
        tunnel_directory=directory,
      )
      monitor_attempt = if monitor_attempt < 4 {
        monitor_attempt + 1
      } else {
        4
      }
      idle_retry_wait(state, idle_timer, delay)
      continue
    }
    if @fs.exists(enabled) {
      tunnel_status(directory, "disconnected")
      attempt = if attempt < 6 { attempt + 1 } else { 6 }
      let delay = if attempt < 6 { 500 * (1 << attempt) } else { 30000 }
      save_diagnostic(
        "orca-tunnel",
        "retry",
        attempt~,
        retry_delay_ms=delay,
        tunnel_directory=directory,
      )
      idle_retry_wait(state, idle_timer, delay)
    }
  }
  tunnel_status(directory, "stopped")
}

///|
async fn check_tunnel(state : Json, directory : String) -> Unit {
  @async.with_timeout(2000, async fn() {
    let (status, _, _) = @process.collect_output(
      "ssh",
      ssh_args(state) + ["-S", control_socket(state, directory), "-O", "check"],
    )
    guard status == 0 else { raise AdapterError("Tunnel not ready") }
    match field(state, "localPort") {
      Some(Json::Number(value, ..)) => {
///|
pub let usage : String = "Usage: orca-env-devsy <status|stop [--force]|resume> --provider <name> [--jobs <n>]\n       orca-env-devsy recipe <create|resume|suspend|destroy|recover|restart>\n       orca-env-devsy <recover|restart>\n"

///|
priv struct BulkOptions {
  provider : String
  jobs : Int32
  force : Bool
}

///|
fn bulk_options(mode : String, args : Array[String]) -> BulkOptions raise {
  let mut provider = None
  let mut jobs = 4
  let mut force = false
  let mut i = 0
  while i < args.length() {
    match args[i] {
      "--provider" if i + 1 < args.length() && provider is None => {
        i += 1
        provider = Some(args[i])
      }
      "--jobs" if i + 1 < args.length() => {
        i += 1
        jobs = @string.parse_int(args[i])
      }
      "--force" if mode == "stop" && !force => force = true
      _ => raise AdapterError("Invalid bulk option: " + args[i])
    }
    i += 1
  }
  guard provider is Some(provider) &&
    valid_context(provider) &&
    jobs > 0 &&
    jobs <= 64 else {
    raise AdapterError(
      "--provider is required; --jobs must be between 1 and 64",
    )
  }
  { provider, jobs, force, }
}

///|
async fn observe_activity(state : Json) -> Json {
  let directory = required(state, "tunnelDirectory")
  let pairing = if @fs.exists(directory + "/pairing-code") {
    @fs.read_file(directory + "/pairing-code").text()
  } else {
    ""
  }
  let script = activity_command(state)
  let (input, writer) = @process.write_to_process()
  defer writer.close()
  let (output, reader) = @process.read_from_process()
  defer output.close()
  let sink = @process.redirect_to_file("/dev/null", shared=true)
  defer sink.close()
  @async.with_timeout(30000, async fn() {
    @async.with_task_group(async fn(group) {
      let child = @process.spawn(
        group,
        "ssh",
        ssh_args(state, services=false) + [script],
        stdin=input,
        stdout=reader,
        stderr=sink,
      )
      let reading = group.spawn(async fn() {
        let buffer = @buffer.Buffer()
        let bytes = FixedArray::make(4096, b'\x00')
        while true {
          let count = output.read(bytes)
          if count == 0 {
            break
          }
          guard buffer.length() + count <= 4194304 else {
            raise AdapterError("Activity response too large")
          }
          buffer.write_bytes(Bytes::from_array(bytes[:count].to_owned()))
        }
        @utf8.decode(buffer.to_bytes())
      })
      let payload : Json = { "pairingCode": pairing }
      writer.write(payload.stringify())
      writer.close()
      guard child.wait() == 0 else {
        raise AdapterError("Remote activity probe failed")
      }
      let value = @json.parse(reading.wait())
      guard field(value, "schemaVersion") == Some(Json::number(1)) &&
        ["idle", "active", "unknown"].contains(required(value, "activity")) else {
        raise AdapterError("Invalid activity response")
      }
      value
    })
  })
}

///|
fn activity_command(state : Json) -> String {
  (if field(state, "orcaVolume") is Some(_) {
    "ORCA_USER_DATA_PATH=/workspaces/.orca/.profile "
  } else {
    ""
  }) +
  "ELECTRON_RUN_AS_NODE=1 \"$HOME/.local/share/orca-env-devsy/orca/current/orca-ide\" -e " +
  quote(activity_probe_source())
}

///|
fn unknown_activity(reason : String) -> Json {
  { "activity": "unknown", "reason": redact_credentials(reason) }
}

///|
async fn bulk_context(state : Json) -> String {
  let selection = @json.parse(state.stringify())
  if selection is Json::Object(fields) {
    fields.remove("context")
  }
  let contexts = @json.parse(
    devsy(
      selection,
      ["--result-format", "json", "context", "list"],
      "bulk-context",
    ),
  )
  guard contexts is Json::Array(items) else {
    raise AdapterError("Invalid context list")
  }
  let selected = items.filter(item => {
    field(item, "default") == Some(Json::boolean(true))
  })
  guard selected.length() == 1 else {
    raise AdapterError("No unique effective Devsy context")
  }
  required(selected[0], "name")
}

///|
async fn bulk_identity(state : Json, provider : String) -> (Bool, Bool) {
  let current = workspace(state)
  match current {
    None => (true, false)
    Some(value) => {
      let actual_provider = field(value, "provider").bind(p => field(p, "name"))
      let in_scope = actual_provider == Some(Json::string(provider)) &&
        field(value, "context")
        .map(c => c == field(state, "context").unwrap())
        .unwrap_or(true)
      if !in_scope {
        save_diagnostic("bulk-workspace", "excluded", evidence={
          "id": required(state, "workspaceId"),
          "context": required(state, "context"),
          "observedContext": field(value, "context").unwrap_or(Json::null()),
          "requestedProvider": provider,
          "observedProvider": actual_provider.unwrap_or(Json::null()),
          "reason": "outside_scope",
        })
      }
      (
        in_scope,
        in_scope && field(value, "uid") == field(state, "workspaceUid"),
      )
    }
  }
}

///|
async fn bulk_one(mode : String, state : Json, options : BulkOptions) -> Json? {
  let id = required(state, "workspaceId")
  let result : Json = {
    "id": id,
    "uid": required(state, "workspaceUid"),
    "context": required(state, "context"),
    "provider": options.provider,
    "identityVerified": false,
    "vmStatus": "unknown",
    "activity": "unknown",
    "outcome": "skipped",
  }
  let mut mutating = false
  try {
    set_field(result, "autoStop", idle_status(state))
    let effective_context = bulk_context(state)
    guard required(state, "context") == effective_context else {
      save_diagnostic("bulk-workspace", "excluded", evidence={
        "id": id,
        "savedContext": required(state, "context"),
        "effectiveContext": effective_context,
        "reason": "context_mismatch",
      })
      return None
    }
    let lock = connection_operation_lock(state)
    defer lock.close()
    let (in_scope, matched) = bulk_identity(state, options.provider)
    guard in_scope else { return None }
    set_field(result, "identityVerified", Json::boolean(matched))
    guard matched else {
      set_field(
        result,
        "evidence",
        unknown_activity("workspace_missing_or_replaced"),
      )
      return Some(result)
    }
    let status = workspace_status(state)
    set_field(result, "vmStatus", Json::string(status))
    let evidence = if status != "Running" {
      unknown_activity("workspace_not_running")
    } else if options.force || mode == "resume" {
      unknown_activity(
        if options.force {
          "forced_without_activity_check"
        } else {
          "resume_does_not_require_activity"
        },
      )
    } else {
      observe_activity(state) catch {
        error => unknown_activity(error.to_string())
      }
    }
    set_field(result, "activity", field(evidence, "activity").unwrap())
    set_field(result, "evidence", evidence)
    save_diagnostic(
      "bulk-observation",
      mode,
      tunnel_directory=required(state, "tunnelDirectory"),
      evidence=result,
    )
    if mode == "status" {
      set_field(result, "outcome", Json::string("observed"))
      return Some(result)
    }
    if mode == "stop" {
      if status == "Stopped" {
        set_field(result, "reason", Json::string("already_stopped"))
      } else if !options.force &&
        (
          status != "Running" ||
          field(evidence, "activity") != Some(Json::string("idle"))
        ) {
        set_field(result, "reason", Json::string("not_idle"))
      } else {
        let (scope, valid) = bulk_identity(state, options.provider)
        guard scope && valid else {
          raise AdapterError("Workspace changed before stop")
        }
        mutating = true
        pause_tunnel(state)
        defer unpause_tunnel(state)
        stop_workspace(state)
        set_field(result, "outcome", Json::string("success"))
      }
    } else if status == "Running" {
      set_field(result, "reason", Json::string("already_running"))
    } else if status != "Stopped" {
      set_field(result, "reason", Json::string("workspace_not_stopped"))
    } else {
      let (scope, valid) = bulk_identity(state, options.provider)
      guard scope && valid else {
        raise AdapterError("Workspace changed before resume")
      }
      mutating = true
      unpause_tunnel(state)
      ignore(
        devsy(
          state,
          [
            "--result-format", "json", "workspace", "up", "--id", id, "--ide-launch",
            "skip",
          ] +
          orca_storage_args(state),
          "workspace-resume",
        ),
      )
      set_field(result, "outcome", Json::string("success"))
      idle_reset(state, "workspace_resumed")
    }
  } catch {
    error => {
      set_field(
        result,
        "outcome",
        Json::string(if mutating { "failed" } else { "skipped" }),
      )
      set_field(result, "evidence", unknown_activity(error.to_string()))
      set_field(
        result,
        "error",
        Json::string(redact_credentials(error.to_string())),
      )
    }
  }
  if mode == "resume" &&
    field(result, "outcome") == Some(Json::string("success")) {
    recover_connection(state) catch {
      error => {
        set_field(result, "outcome", Json::string("failed"))
        set_field(
          result,
          "error",
          Json::string(redact_credentials(error.to_string())),
        )
      }
    }
  }
  save_diagnostic("bulk-workspace", mode, evidence=result)
  Some(result)
}

