    for (const f of [{ truncated: true }, { verdict: "unverifiable" }, { connected: false }, { age: 6000 }, { nativeError: true }, { authoritative: false }, { pairing: "" }]) {
      expect((await probe(f)).activity).toBe("unknown");
    }
  });
});
